mapper.select:
select od.name , sum(od.number) as number
from order_detail od
inner join sky_take_out.orders o on od.order_id = o.id


        and o.order_time >= #{startTime}


        and o.order_time <= #{endTime}


        and o.status = #{status}


group by od.dish_id, od.name
order by number desc
limit 10
